import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000,
  ssl: { rejectUnauthorized: false } // dev cert
});

// Session store - in-memory for simplicity
const sessions = new Map();

// Middleware: extract user from session cookie
app.use((req, res, next) => {
  const sid = req.headers['x-session-id'];
  if (sid && sessions.has(sid)) {
    req.user = sessions.get(sid);
  }
  next();
});

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing credentials' });

  const hash = crypto.createHash('sha256').update(password).digest('hex');
  const result = await pool.query(
    'SELECT id, username, role FROM users WHERE username = $1 AND password_hash = $2',
    [username, hash]
  );

  if (result.rows.length === 0) return res.status(401).json({ error: 'Invalid credentials' });

  const sid = crypto.randomBytes(32).toString('hex');
  sessions.set(sid, result.rows[0]);
  res.json({ session_id: sid, user: result.rows[0] });
});

// Document search - supports advanced filtering
app.get('/api/documents/search', async (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'Unauthorized' });

  const { q, category, sort_by, order } = req.query;

  // Build search query with user's tenant isolation
  let baseQuery = `SELECT d.id, d.title, d.category, d.created_at, d.owner_id 
    FROM documents d WHERE d.tenant_id = $1`;
  const params = [req.user.tenant_id];
  let paramIdx = 2;

  if (q) {
    baseQuery += ` AND d.title ILIKE $${paramIdx}`;
    params.push(`%${q}%`);
    paramIdx++;
  }

  if (category) {
    baseQuery += ` AND d.category = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  // Sort - validated against allowlist... or so we think
  const allowedSorts = ['title', 'created_at', 'category'];
  const sortField = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
  const sortOrder = order === 'asc' ? 'ASC' : 'DESC';

  // BUG: sort_by is validated but a second code path exists
  // The 'fields' parameter allows selecting which columns to return
  const fields = req.query.fields;
  if (fields) {
    // Developer intended this for frontend optimization
    // but it allows injection via column specification
    baseQuery = `SELECT ${fields} FROM documents d WHERE d.tenant_id = $1`;
    // Re-append filters
    if (q) {
      baseQuery += ` AND d.title ILIKE $2`;
    }
  }

  baseQuery += ` ORDER BY ${sortField} ${sortOrder} LIMIT 50`;

  try {
    const result = await pool.query(baseQuery, params);
    res.json({ documents: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Document detail with file download
app.get('/api/documents/:id', async (req, res) => {
  if (!req.user) return res.status(401).json({ error: 'Unauthorized' });

  const docId = parseInt(req.params.id);
  if (isNaN(docId)) return res.status(400).json({ error: 'Invalid ID' });

  const result = await pool.query(
    'SELECT * FROM documents WHERE id = $1 AND tenant_id = $2',
    [docId, req.user.tenant_id]
  );

  if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
  res.json({ document: result.rows[0] });
});

// Health check exposing version info
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    version: process.env.APP_VERSION || '2.3.1',
    node: process.version,
    uptime: process.uptime()
  });
});

app.listen(3000, () => console.log('Document service running on :3000'));
